new = '''"""SyncWise computational module; exact planning, certification and audit.

Legacy stochastic synchronisation heuristics are retained after the exact part;
they are not used by the exact pipeline.
"""
import heapq

import numpy as np

import para
import topo
import utils
from topo import AGE_SHIFT, AGE_MULT, AGE_MASK
from para import is_int

NS_AS = 1000000000


# ------------------------------------------------------------- exact envelope

def run_dijkstra(fab, g):
    """Lexicographic (bound, age) shortest paths over the periodic lineage
    graph sampled with guard setting g.  Returns (best, prevv, prevk)."""
    V = fab.V
    N = fab.N
    indptr = fab.indptr
    edst = fab.edst
    mkey = fab.mkey
    egmax = fab.egmax
    ekind = fab.ekind
    wkey = fab.wkey
    SH = fab.SHIFT
    VM = fab.VMASK
    best = [None] * V
    prevv = [-1] * V
    prevk = [0] * V
    heap = []
    push = heapq.heappush
    pop = heapq.heappop
    for v in fab.anchor_verts:
        best[v] = 0
        push(heap, v)
    while heap:
        item = pop(heap)
        nk = item >> SH
        v = item & VM
        if best[v] != nk:
            continue
        w = v + N
        if w >= V:
            w -= V
        kk = nk + wkey[v]
        bw = best[w]
        if bw is None or kk < bw:
            best[w] = kk
            prevv[w] = v
            prevk[w] = -1
            push(heap, (kk << SH) | w)
        s = indptr[v]
        e = indptr[v + 1]
        while s < e:
            if egmax[s] >= g:
                nv = edst[s]
                kk = nk + mkey[s]
                b = best[nv]
                if b is None or kk < b:
                    best[nv] = kk
                    prevv[nv] = v
                    prevk[nv] = ekind[s]
                    push(heap, (kk << SH) | nv)
            s += 1
    return best, prevv, prevk


def summarise(fab, best):
    """peak (or None when some phase-device stays unknown) and warmup cycle."""
    V = fab.V
    N = fab.N
    P = fab.P
    wcost = fab.wcost
    peak = 0
    warm = 0
    for p in range(P):
        base = p * N
        for i in range(N):
            v = base + i
            b = best[v]
            if b is None:
                return None, 0
            val = (b >> AGE_SHIFT) + wcost[v]
            if val > peak:
                peak = val
            age = b & AGE_MASK
            if age > p:
                k = -((age - p) // -P)
                if k > warm:
                    warm = k
    return peak, warm


def evaluate_guards(fab):
    """Exact all-time peak for every supported guard setting, the smallest
    safe setting and the envelope witness of that setting."""
    guards = fab.guards
    gm = np.asarray(fab.egmax)
    peaks = []
    sel = None
    selres = None
    last_g = None
    last_res = None
    last_peak = None
    dead = False
    for g in guards:
        if dead:
            peaks.append(None)
            continue
        if last_g is not None and not np.any((gm >= last_g) & (gm < g)):
            peak = last_peak
            res = last_res
        else:
            best, prevv, prevk = run_dijkstra(fab, g)
            peak, warm = summarise(fab, best)
            res = (best, prevv, prevk, warm)
            last_res = res
            last_peak = peak
            last_g = g
        peaks.append(peak)
        if peak is None:
            dead = True
        elif sel is None and g * NS_AS >= peak + fab.reconfig * NS_AS:
            sel = g
            selres = res
    return peaks, sel, selres


def matrices(fab, res):
    best, prevv, prevk, warm = res
    V = fab.V
    N = fab.N
    P = fab.P
    bounds = [None] * V
    ages = [None] * V
    preds = [None] * V
    for v in range(V):
        b = best[v]
        if b is not None:
            bounds[v] = b >> AGE_SHIFT
            ages[v] = b & AGE_MASK
            pv = prevv[v]
            if pv >= 0:
                preds[v] = [pv, int(prevk[v])]
    brows = [bounds[p * N:(p + 1) * N] for p in range(P)]
    arows = [ages[p * N:(p + 1) * N] for p in range(P)]
    prows = [preds[p * N:(p + 1) * N] for p in range(P)]
    return brows, arows, prows, warm


# ------------------------------------------------------------------- planning

def compile_plan(profile, fabric):
    cal = para.build_calib(profile)
    if not cal.feasible:
        return {"status": "inconsistent", "cycle": cal.cycle}
    fab = topo.Fabric(fabric, cal)
    peaks, sel, res = evaluate_guards(fab)
    if sel is None:
        return {"status": "ok", "profile": para.calib_artifact(cal),
                "period_rounds": fab.P, "peaks_as": peaks, "guard_ns": None,
                "bounds_as": None, "age_rounds": None, "pred": None,
                "warmup_cycle": None}
    brows, arows, prows, warm = matrices(fab, res)
    return {"status": "ok", "profile": para.calib_artifact(cal),
            "period_rounds": fab.P, "peaks_as": peaks, "guard_ns": sel,
            "bounds_as": brows, "age_rounds": arows, "pred": prows,
            "warmup_cycle": warm}


# --------------------------------------------------------------------- audit

PLAN_KEYS = {"status", "profile", "period_rounds", "peaks_as", "guard_ns",
             "bounds_as", "age_rounds", "pred", "warmup_cycle"}
CAL_KEYS = {"status", "upper_ps", "pred"}


def _flatten(mat, P, N):
    if not isinstance(mat, list) or len(mat) != P:
        return None
    out = []
    for row in mat:
        if not isinstance(row, list) or len(row) != N:
            return None
        out.extend(row)
    return out


def check_calib_cert(cal, prop):
    K = cal.K
    if not isinstance(prop, dict) or set(prop.keys()) != CAL_KEYS:
        return False
    if prop['status'] != 'ok':
        return False
    up = prop['upper_ps']
    pr = prop['pred']
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    two_m = 2 * cal.M
    heads = cal.heads
    tails = cal.tails
    wts = cal.weights
    truth = cal.upper
    for a in range(K):
        ra = up[a]
        pa = pr[a]
        if not isinstance(ra, list) or len(ra) != K:
            return False
        if not isinstance(pa, list) or len(pa) != K:
            return False
        ta = truth[a]
        for b in range(K):
            x = ra[b]
            if not is_int(x) or x != ta[b]:
                return False
        if pa[a] is not None:
            return False
        sums = [None] * K
        state = bytearray(K)
        state[a] = 2
        sums[a] = 0
        for b in range(K):
            if b == a:
                continue
            stack = []
            cur = b
            ok = False
            base = 0
            while True:
                st = state[cur]
                if st == 2:
                    base = sums[cur]
                    ok = True
                    break
                if st == 1:
                    break
                e = pa[cur]
                if not is_int(e) or e < 0 or e >= two_m:
                    break
                if heads[e] != cur:
                    break
                state[cur] = 1
                stack.append(cur)
                cur = tails[e]
            if not ok:
                return False
            acc = base
            while stack:
                nd = stack.pop()
                acc += wts[pa[nd]]
                sums[nd] = acc
                state[nd] = 2
            if sums[b] != ra[b]:
                return False
    return True


def check_plan_witness(fab, g, bounds, ages, preds):
    N = fab.N
    P = fab.P
    wcost = fab.wcost
    is_anchor = fab.is_anchor
    step_info = fab.step_info
    for p in range(P):
        base = p * N
        prev_base = (p - 1) % P * N
        for i in range(N):
            v = base + i
            bv = bounds[v]
            if bv is None:
                if ages[v] is not None or preds[v] is not None:
                    return False
                continue
            av = ages[v]
            if not is_int(bv) or not is_int(av) or bv < 0 or av < 0:
                return False
            pr = preds[v]
            if is_anchor[v]:
                if pr is not None or bv != 0 or av != 0:
                    return False
                continue
            if not isinstance(pr, list) or len(pr) != 2:
                return False
            pv = pr[0]
            kind = pr[1]
            if not is_int(pv) or not is_int(kind):
                return False
            if pv < 0 or pv >= fab.V:
                return False
            bp = bounds[pv]
            ap = ages[pv]
            if bp is None or ap is None:
                return False
            if kind == -1:
                if pv != prev_base + i:
                    return False
                if bv != bp + wcost[pv] or av != ap + 1:
                    return False
            else:
                si = step_info(kind, pv // N, g)
                if si is None:
                    return False
                dv, cost, adel, src = si
                if dv != v or pv % N != src:
                    return False
                if bv != bp + cost or av != ap + adel:
                    return False
    return True


def _audit(profile, fabric, proposal):
    if not isinstance(proposal, dict):
        return False
    n = int(fabric['n'])
    Q = len(fabric['slices'])
    P = utils.declared_period(int(fabric['interval_ns']), int(fabric['slice_ns']), Q)
    guards = fabric['guards_ns']
    cal = para.build_calib(profile)
    if not cal.feasible:
        if set(proposal.keys()) != {"status", "cycle"}:
            return False
        if proposal['status'] != 'inconsistent':
            return False
        cyc = proposal['cycle']
        if not isinstance(cyc, list) or len(cyc) > cal.K:
            return False
        return para.cycle_weight_ok(cyc, cal.tails, cal.heads, cal.weights)
    if set(proposal.keys()) != PLAN_KEYS:
        return False
    if proposal['status'] != 'ok':
        return False
    if not is_int(proposal['period_rounds']) or proposal['period_rounds'] != P:
        return False
    pk = proposal['peaks_as']
    if not isinstance(pk, list) or len(pk) != len(guards):
        return False
    for x in pk:
        if x is not None and not is_int(x):
            return False
    gn = proposal['guard_ns']
    if gn is not None and not is_int(gn):
        return False
    bm = proposal['bounds_as']
    am = proposal['age_rounds']
    pmx = proposal['pred']
    wc = proposal['warmup_cycle']
    if gn is None:
        if bm is not None or am is not None or pmx is not None or wc is not None:
            return False
    else:
        if wc is not None and not is_int(wc):
            return False
        if bm is not None and _flatten(bm, P, n) is None:
            return False
        if am is not None and _flatten(am, P, n) is None:
            return False
        if pmx is not None:
            if not isinstance(pmx, list) or len(pmx) != P:
                return False
            for row in pmx:
                if not isinstance(row, list) or len(row) != n:
                    return False
    if not check_calib_cert(cal, proposal['profile']):
        return False
    fab = topo.Fabric(fabric, cal)
    peaks, sel, res = evaluate_guards(fab)
    if len(peaks) != len(pk):
        return False
    for a, b in zip(peaks, pk):
        if a != b or (a is None) != (b is None):
            return False
    if sel != gn:
        return False
    if sel is None:
        return True
    brows, arows, prows, warm = matrices(fab, res)
    if wc != warm:
        return False
    fb = _flatten(bm, P, n)
    fa = _flatten(am, P, n)
    if fb is None or fa is None:
        return False
    tfb = [x for row in brows for x in row]
    tfa = [x for row in arows for x in row]
    if fb != tfb or fa != tfa:
        return False
    fp = []
    for row in pmx:
        fp.extend(row)
    if not check_plan_witness(fab, sel, fb, fa, fp):
        return False
    return True


def audit(profile, fabric, proposal):
    try:
        return {"valid": bool(_audit(profile, fabric, proposal))}
    except Exception:
        return {"valid": False}


'''
